// Charts and chartsheets created with the streaming writer (stream.xlsx.WorkbookWriter): worksheet.addChart and
// writer.addChartsheet validate the options as the document API does (src/doc/chart.ts) and the chart parts are
// generated by the same code, when the workbook is committed, their cached values captured from the cells as the rows are
// written (src/stream/xlsx/stream-chart.ts). Sample files for Excel are written to spec/out/charts-samples/streaming-*.xlsx;
// with OOXML_SCHEMAS set (spec/utils/xmllint.js), the chart, drawing and chartsheet parts, and the worksheets with a
// drawing, are validated against the schemas.
const fs = require("fs");
const path = require("path");
const { PassThrough } = require("stream");
const { strFromU8 } = require("fflate");
const { unzipParts, zipParts } = require("../utils/xlsx-tamper");
const { schemaValidator, validateDrawingParts } = require("../utils/xmllint");

const ExcelJS = verquire("exceljs");

const SAMPLES = path.join(__dirname, "../out/charts-samples");
const IMAGE_FILENAME = path.join(__dirname, "data/image.png");
const REL_DRAWING = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing";
const REL_IMAGE = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/image";
const CT_CHART = "application/vnd.openxmlformats-officedocument.drawingml.chart+xml";
const CT_DRAWING = "application/vnd.openxmlformats-officedocument.drawing+xml";
const CT_CHARTSHEET = "application/vnd.openxmlformats-officedocument.spreadsheetml.chartsheet+xml";
const DATE = new Date("2024-01-02T03:04:05Z");

// commits a streamed workbook into memory: the xlsx buffer
async function streamBuffer(build, options = {}) {
    const stream = new PassThrough();
    const chunks = [];
    stream.on("data", (chunk) => chunks.push(chunk));
    const wb = new ExcelJS.stream.xlsx.WorkbookWriter({ stream, created: DATE, modified: DATE, ...options });
    await build(wb);
    await wb.commit();
    return Buffer.concat(chunks);
}

const parts = (buffer) => unzipParts(buffer);
const text = (buffer, name) => {
    const part = parts(buffer)[name];
    return part ? strFromU8(part) : undefined;
};

async function reload(buffer) {
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.load(buffer);
    return wb;
}

// the chart, drawing and chartsheet parts, and the worksheets with a drawing (their x14ac / mc attributes, which the
// schema does not know, removed), validated against the schemas when they are available
const validateWorksheet = schemaValidator();
function validate(buffer, label) {
    const all = parts(buffer);
    const result = validateDrawingParts(all, path.join(SAMPLES, "xml", `streaming-${label}`));
    if (!result) {
        return;
    }
    expect(result.ok, `${label}: ${result.output}`).to.be.true();
    expect(result.count).to.be.greaterThan(0);
    const dir = path.join(SAMPLES, "xml", `streaming-${label}`);
    const sheets = Object.keys(all).filter((name) => /^xl\/worksheets\/sheet\d+\.xml$/.test(name));
    const files = [];
    for (const name of sheets) {
        const xml = strFromU8(all[name]);
        if (xml.includes("<drawing ")) {
            const file = path.join(dir, name.replace(/\//g, "-"));
            fs.writeFileSync(file, xml.replace(/ mc:Ignorable="x14ac"/, "").replace(/ x14ac:dyDescent="[^"]*"/g, ""));
            files.push(file);
        }
    }
    if (files.length) {
        const sheetResult = validateWorksheet("sml.xsd", files);
        expect(sheetResult.ok, `${label} worksheets: ${sheetResult.output}`).to.be.true();
    }
}

// the data of the charts: A1:E5 (months, two series, a formula series, dates), F1:G1 merged (a series name)
function fill(ws, { commit = false } = {}) {
    const rows = [
        ["Month", "North", "South", "Total", "When"],
        ["Jan", 10, 7.5],
        ["Feb", 12, null],
        ["Mar", -9, 11],
        ["Apr", 14, 10],
    ];
    rows.forEach((values, index) => {
        const row = ws.getRow(index + 1);
        row.values = values;
        if (index > 0) {
            row.getCell(4).value = { formula: `B${index + 1}+C${index + 1}`, result: (values[1] || 0) + (values[2] || 0) };
            row.getCell(5).value = new Date(Date.UTC(2024, index - 1, 15));
            row.getCell(2).numFmt = "0.0";
        } else {
            row.getCell(6).value = "Merged name";
        }
    });
    ws.mergeCells("F1:G1");
    if (commit) {
        for (let r = 1; r <= rows.length; r++) {
            ws.getRow(r).commit();
        }
    }
}

const CHART = {
    type: "line",
    title: "Sales & <more>",
    anchor: "H2:O18",
    series: [
        { name: { ref: "B1" }, categories: "A2:A5", values: "B2:B5", color: "#1F77B4" },
        { name: { ref: "G1" }, categories: "E2:E5", values: "C2:C5" },
        { name: "Total", categories: "A2:A5", values: "D2:D5" },
    ],
    axes: { value: { title: "Units", min: -10, max: 30 } },
};

describe("Charts of the streaming writer", () => {
    it("writes the chart of a worksheet: drawing, relationships, content types, element order", async () => {
        let chart;
        const buffer = await streamBuffer((wb) => {
            const ws = wb.addWorksheet("Data");
            chart = ws.addChart(CHART);
            expect(chart.type).to.equal("line");
            expect(chart.title).to.equal("Sales & <more>");
            expect(ws.getCharts()).to.deep.equal([chart]);
            fill(ws, { commit: true });
            ws.getRow(6).getCell(1).note = "a note";
            ws.getColumn(3).addPageBreak();
        });
        validate(buffer, "basic");
        const sheet = text(buffer, "xl/worksheets/sheet1.xml");
        // CT_Worksheet: ... rowBreaks, colBreaks, drawing, legacyDrawing, picture
        expect(sheet).to.match(/<\/colBreaks><drawing r:id="(rId\d+)"\/><legacyDrawing r:id="rId\d+"\/><\/worksheet>$/);
        const [, drawingId] = /<drawing r:id="(rId\d+)"\/>/.exec(sheet);
        expect(text(buffer, "xl/worksheets/_rels/sheet1.xml.rels")).to.include(
            `<Relationship Id="${drawingId}" Type="${REL_DRAWING}" Target="../drawings/drawing1.xml"/>`
        );
        const contentTypes = text(buffer, "[Content_Types].xml");
        expect(contentTypes).to.include(`<Override PartName="/xl/drawings/drawing1.xml" ContentType="${CT_DRAWING}"/>`);
        expect(contentTypes).to.include(`<Override PartName="/xl/charts/chart1.xml" ContentType="${CT_CHART}"/>`);
        expect(text(buffer, "xl/drawings/_rels/drawing1.xml.rels")).to.include('Target="../charts/chart1.xml"');

        const xml = text(buffer, "xl/charts/chart1.xml");
        expect(xml).to.include("<a:t>Sales &amp; &lt;more&gt;</a:t>");
        expect(xml).to.include(
            '<c:val><c:numRef><c:f>Data!$B$2:$B$5</c:f><c:numCache><c:formatCode>0.0</c:formatCode><c:ptCount val="4"/><c:pt idx="0"><c:v>10</c:v></c:pt><c:pt idx="1"><c:v>12</c:v></c:pt><c:pt idx="2"><c:v>-9</c:v></c:pt><c:pt idx="3"><c:v>14</c:v></c:pt></c:numCache></c:numRef></c:val>'
        );
        // an empty cell has no point, nor a cell merged into another one (Excel reads it empty)
        expect(xml).to.include(
            '<c:f>Data!$C$2:$C$5</c:f><c:numCache><c:formatCode>General</c:formatCode><c:ptCount val="4"/><c:pt idx="0"><c:v>7.5</c:v></c:pt><c:pt idx="2">'
        );
        expect(xml).to.include('<c:f>Data!$G$1</c:f><c:strCache><c:ptCount val="1"/></c:strCache>');
        // formula results, dates as serial numbers
        expect(xml).to.include(
            '<c:f>Data!$D$2:$D$5</c:f><c:numCache><c:formatCode>General</c:formatCode><c:ptCount val="4"/><c:pt idx="0"><c:v>17.5</c:v>'
        );
        expect(xml).to.include(
            '<c:f>Data!$E$2:$E$5</c:f><c:numCache><c:formatCode>mm-dd-yy</c:formatCode><c:ptCount val="4"/><c:pt idx="0"><c:v>45306</c:v>'
        );
    });

    it("generates the same chart and drawing parts as the document writer, byte for byte", async () => {
        const doc = new ExcelJS.Workbook();
        const docSheet = doc.addWorksheet("Data");
        fill(docSheet);
        docSheet.addChart(CHART);
        docSheet.addChart({
            type: "scatter",
            line: true,
            anchor: { tl: { col: 8.5, row: 20 }, ext: { width: 400, height: 300 } },
            series: [{ xValues: "B2:B5", yValues: "C2:C5" }],
        });
        const docParts = parts(await doc.xlsx.writeBuffer());

        // rows committed after the charts are added, or still in memory when the worksheet is committed
        for (const commit of [true, false]) {
            const streamed = parts(
                await streamBuffer((wb) => {
                    const ws = wb.addWorksheet("Data");
                    ws.addChart(CHART);
                    ws.addChart({
                        type: "scatter",
                        line: true,
                        anchor: { tl: { col: 8.5, row: 20 }, ext: { width: 400, height: 300 } },
                        series: [{ xValues: "B2:B5", yValues: "C2:C5" }],
                    });
                    fill(ws, { commit });
                })
            );
            for (const name of [
                "xl/charts/chart1.xml",
                "xl/charts/chart2.xml",
                "xl/drawings/drawing1.xml",
                "xl/drawings/_rels/drawing1.xml.rels",
            ]) {
                expect(strFromU8(streamed[name]), `${name} (commit: ${commit})`).to.equal(strFromU8(docParts[name]));
            }
        }
    });

    it("shows the data of another worksheet, committed before or after the worksheet of the chart", async () => {
        const buffer = await streamBuffer(async (wb) => {
            const summary = wb.addWorksheet("Summary");
            const data = wb.addWorksheet("My Data");
            // the chart of Summary shows My Data; Summary is committed before the rows of My Data are written
            summary.addChart({ type: "column", anchor: "B2:I16", series: [{ categories: "'My Data'!A2:A5", values: "'my data'!B2:B5" }] });
            summary.getCell("A1").value = "Summary";
            await summary.commit();
            // a chart of My Data showing the cells of Summary (committed: no cache) and its own (cached)
            data.addChart({
                type: "bar",
                anchor: "D2:J9",
                series: [
                    { name: { ref: "Summary!A1" }, values: "Summary!B1:B2" },
                    { name: { ref: "B1" }, values: "B2:B5" },
                ],
            });
            fill(data, { commit: true });
        });
        validate(buffer, "cross-sheet");
        expect(text(buffer, "xl/worksheets/sheet1.xml")).to.include('<drawing r:id="rId1"/>');
        expect(text(buffer, "xl/worksheets/sheet2.xml")).to.include('<drawing r:id="rId1"/>');
        const chart1 = text(buffer, "xl/charts/chart1.xml");
        expect(chart1).to.include("<c:f>&apos;My Data&apos;!$A$2:$A$5</c:f>");
        expect(chart1).to.include('<c:pt idx="3"><c:v>Apr</c:v></c:pt>');
        expect(chart1).to.include(
            '<c:f>&apos;My Data&apos;!$B$2:$B$5</c:f><c:numCache><c:formatCode>0.0</c:formatCode><c:ptCount val="4"/><c:pt idx="0"><c:v>10</c:v>'
        );
        const chart2 = text(buffer, "xl/charts/chart2.xml");
        expect(chart2).to.include(
            '<c:tx><c:strRef><c:f>Summary!$A$1</c:f></c:strRef></c:tx><c:invertIfNegative val="0"/><c:val><c:numRef><c:f>Summary!$B$1:$B$2</c:f></c:numRef></c:val>'
        );
        expect(chart2).to.include("<c:v>North</c:v>");
        expect(text(buffer, "xl/drawings/_rels/drawing2.xml.rels")).to.include('Target="../charts/chart2.xml"');
    });

    it("writes the series of rows committed before the chart without cache, captures the others", async () => {
        const buffer = await streamBuffer((wb) => {
            const ws = wb.addWorksheet("Data");
            ws.addRow(["Name", 1]).commit();
            ws.addRow(["Two", 2]);
            ws.addRow(["Three", 3]);
            // series 1: a row committed (A1, B1): no cache for any of its ranges; series 2: rows in memory, captured
            ws.addChart({
                type: "line",
                anchor: "D1:J9",
                series: [
                    { name: { ref: "A1" }, categories: "A2:A3", values: "B1:B3" },
                    { name: "Kept", categories: "A2:A3", values: "B2:B3" },
                ],
            });
            wb.addChartsheet("Chart", { type: "scatter", series: [{ xValues: "Data!B1:B2", yValues: "Data!B2:B3" }] });
        });
        validate(buffer, "committed-rows");
        const line = text(buffer, "xl/charts/chart1.xml");
        expect(line).to.include(
            "<c:tx><c:strRef><c:f>Data!$A$1</c:f></c:strRef></c:tx><c:cat><c:strRef><c:f>Data!$A$2:$A$3</c:f></c:strRef></c:cat><c:val><c:numRef><c:f>Data!$B$1:$B$3</c:f></c:numRef></c:val>"
        );
        expect(line).to.include(
            '<c:cat><c:strRef><c:f>Data!$A$2:$A$3</c:f><c:strCache><c:ptCount val="2"/><c:pt idx="0"><c:v>Two</c:v></c:pt><c:pt idx="1"><c:v>Three</c:v></c:pt></c:strCache></c:strRef></c:cat><c:val><c:numRef><c:f>Data!$B$2:$B$3</c:f><c:numCache><c:formatCode>General</c:formatCode><c:ptCount val="2"/>'
        );
        // the x values of a scatter chart without cache are numbers
        expect(text(buffer, "xl/charts/chart2.xml")).to.include(
            "<c:xVal><c:numRef><c:f>Data!$B$1:$B$2</c:f></c:numRef></c:xVal><c:yVal><c:numRef><c:f>Data!$B$2:$B$3</c:f></c:numRef></c:yVal>"
        );
        // carried as written once read back
        const wb = await reload(buffer);
        expect(strFromU8(parts(await wb.xlsx.writeBuffer())["xl/charts/chart1.xml"])).to.equal(line);
    });

    it("writes a chart added once its data is committed (another worksheet) without cache", async () => {
        const buffer = await streamBuffer(async (wb) => {
            const data = wb.addWorksheet("Data");
            fill(data, { commit: true });
            await data.commit();
            const summary = wb.addWorksheet("Summary");
            summary.addChart({
                type: "column",
                anchor: "A1:H16",
                series: [{ name: { ref: "Data!B1" }, categories: "Data!A2:A5", values: "Data!B2:B5" }],
            });
            wb.addChartsheet("Chart", { type: "pie", series: [{ categories: "Data!A2:A5", values: "Data!B2:B5" }] });
        });
        validate(buffer, "data-committed");
        for (const name of ["xl/charts/chart1.xml", "xl/charts/chart2.xml"]) {
            const xml = text(buffer, name);
            expect(xml).to.include("<c:f>Data!$B$2:$B$5</c:f></c:numRef>");
            expect(xml).to.not.include("Cache>");
        }
    });

    it("refuses a chart once its worksheet is committed; a chart removed is not written", async () => {
        const buffer = await streamBuffer(async (wb) => {
            const ws = wb.addWorksheet("Data");
            const removed = ws.addChart({ type: "pie", anchor: "C1:H9", series: [{ values: "A1:A3" }] });
            const kept = ws.addChart({ type: "doughnut", anchor: "C10:H19", series: [{ values: "A1:A3" }] });
            removed.remove();
            removed.remove();
            expect(ws.getCharts()).to.deep.equal([kept]);
            ws.addRow([1]);
            await ws.commit();
            expect(() => ws.addChart({ type: "pie", anchor: "C1:H9", series: [{ values: "A1:A3" }] })).to.throw(
                "Invalid Operation: the worksheet has been committed"
            );
            expect(() => kept.remove()).to.throw("Invalid Operation: the worksheet has been committed");
        });
        expect(Object.keys(parts(buffer)).filter((name) => name.startsWith("xl/charts/"))).to.deep.equal(["xl/charts/chart1.xml"]);
        expect(text(buffer, "xl/charts/chart1.xml")).to.include("<c:doughnutChart>");
        // a worksheet whose charts were all removed has no drawing
        const empty = await streamBuffer((wb) => {
            const ws = wb.addWorksheet("Data");
            ws.addChart({ type: "pie", anchor: "C1:H9", series: [{ values: "A1:A3" }] }).remove();
            ws.addRow([1]);
        });
        expect(Object.keys(parts(empty)).filter((name) => /^xl\/(charts|drawings)\//.test(name))).to.deep.equal([]);
        expect(text(empty, "xl/worksheets/sheet1.xml")).to.not.include("<drawing");
    });

    it("validates the options as the document API does", () => {
        const wb = new ExcelJS.stream.xlsx.WorkbookWriter({ stream: new PassThrough() });
        const ws = wb.addWorksheet("Data");
        const doc = new ExcelJS.Workbook().addWorksheet("Data");
        const invalid = [
            { type: "radar", anchor: "A1:B2", series: [{ values: "A1:A2" }] },
            { type: "line", anchor: "A1:B2", series: [{ values: "A1:B2" }] },
            { type: "line", anchor: "A1:B2", series: [{ values: "Nope!A1:A2" }] },
            { type: "pie", anchor: "A1:B2", axes: {}, series: [{ values: "A1:A2" }] },
            { type: "line", series: [{ values: "A1:A2" }] },
            { type: "line", anchor: "A1:B2", series: [] },
            { type: "scatter", anchor: "A1:B2", series: [{ values: "A1:A2" }] },
        ];
        for (const options of invalid) {
            let expected;
            try {
                doc.addChart(options);
            } catch (error) {
                expected = error.message;
            }
            expect(expected, JSON.stringify(options)).to.be.a("string");
            expect(() => ws.addChart(options)).to.throw(expected);
        }
        expect(ws.getCharts()).to.deep.equal([]);
    });

    it("numbers the drawings and the charts of several worksheets, beside a background image and notes", async () => {
        const buffer = await streamBuffer((wb) => {
            const imageId = wb.addImage({ filename: IMAGE_FILENAME, extension: "png" });
            const first = wb.addWorksheet("First");
            const plain = wb.addWorksheet("Plain");
            const second = wb.addWorksheet("Second");
            first.addBackgroundImage(imageId);
            first.addChart({ type: "column", anchor: "D2:J12", series: [{ values: "A1:A3" }] });
            first.addChart({ type: "area", anchor: "D14:J24", series: [{ values: "A1:A3" }] });
            second.addChart({ type: "pie", anchor: "D2:J12", series: [{ values: "First!A1:A3" }] });
            first.getCell("B1").note = "note";
            for (const ws of [first, plain, second]) {
                ws.getCell("A1").value = 1;
                ws.getRow(1).commit();
                ws.addRow([2]).commit();
                ws.addRow([3]);
            }
        });
        validate(buffer, "numbering");
        const sheet1 = text(buffer, "xl/worksheets/sheet1.xml");
        expect(sheet1).to.match(/<drawing r:id="rId(\d+)"\/><legacyDrawing r:id="rId\d+"\/><picture r:id="rId\d+"\/><\/worksheet>$/);
        const rels1 = text(buffer, "xl/worksheets/_rels/sheet1.xml.rels");
        const ids = [...rels1.matchAll(/Id="(rId\d+)"/g)].map((match) => match[1]);
        expect(new Set(ids).size).to.equal(ids.length);
        expect(rels1).to.include(`Type="${REL_DRAWING}" Target="../drawings/drawing1.xml"`);
        expect(rels1).to.include(`Type="${REL_IMAGE}" Target="../media/image0.png"`);
        expect(text(buffer, "xl/worksheets/sheet2.xml")).to.not.include("<drawing");
        expect(text(buffer, "xl/worksheets/sheet3.xml")).to.include("<drawing ");
        expect(text(buffer, "xl/worksheets/_rels/sheet3.xml.rels")).to.include("../drawings/drawing2.xml");
        // two charts in drawing1, one in drawing2; unique shape ids in each drawing
        expect(text(buffer, "xl/drawings/_rels/drawing1.xml.rels")).to.include("../charts/chart1.xml").and.include("../charts/chart2.xml");
        expect(text(buffer, "xl/drawings/_rels/drawing2.xml.rels")).to.include("../charts/chart3.xml");
        const drawing1 = text(buffer, "xl/drawings/drawing1.xml");
        expect([...drawing1.matchAll(/<xdr:cNvPr id="(\d+)" name="([^"]+)"/g)].map((m) => [m[1], m[2]])).to.deep.equal([
            ["1", "Chart 1"],
            ["2", "Chart 2"],
        ]);
        const contentTypes = text(buffer, "[Content_Types].xml");
        expect(contentTypes).to.include('<Default Extension="png" ContentType="image/png"/>');
        for (const n of [1, 2, 3]) {
            expect(contentTypes).to.include(`<Override PartName="/xl/charts/chart${n}.xml" ContentType="${CT_CHART}"/>`);
        }
        expect(contentTypes.match(/drawing\+xml/g)).to.have.length(2);
        expect(parts(buffer)["xl/media/image0.png"]).to.deep.equal(new Uint8Array(fs.readFileSync(IMAGE_FILENAME)));
    });

    it("is carried once read back, the second write byte for byte the first", async () => {
        const buffer = await streamBuffer((wb) => {
            const ws = wb.addWorksheet("Data");
            ws.addChart(CHART);
            wb.addChartsheet(
                "Chart",
                { type: "column", series: [{ values: "Data!B2:B5", categories: "Data!A2:A5" }] },
                { state: "hidden" }
            );
            fill(ws, { commit: true });
        });
        const wb = await reload(buffer);
        expect(wb.chartsheets).to.deep.equal([{ id: 2, name: "Chart", state: "hidden" }]);
        expect(wb.getWorksheet("Data")._charts).to.have.length(1);
        const first = parts(await wb.xlsx.writeBuffer());
        const second = parts(await (await reload(Buffer.from(zipParts(first)))).xlsx.writeBuffer());
        const charted = (all) =>
            Object.keys(all)
                .filter((name) => /^xl\/(charts|drawings|chartsheets)\//.test(name))
                .sort();
        expect(charted(second)).to.deep.equal(charted(first));
        expect(charted(first)).to.include.members(["xl/charts/chart1.xml", "xl/charts/chart2.xml", "xl/chartsheets/sheet1.xml"]);
        for (const name of charted(first)) {
            expect(strFromU8(second[name]), name).to.equal(strFromU8(first[name]));
        }
        // the chart parts generated by the streaming writer are carried as they were written
        expect(strFromU8(first["xl/charts/chart1.xml"])).to.equal(text(buffer, "xl/charts/chart1.xml"));
        expect(strFromU8(first["xl/charts/chart2.xml"])).to.equal(text(buffer, "xl/charts/chart2.xml"));
    });

    it("captures huge ranges in time linear in the rows written, keeping only the cells with a value", async function () {
        this.timeout(20000);
        // 255 series of whole columns (1,048,576 rows each), and a whole row
        const run = async (rows) => {
            const started = process.hrtime.bigint();
            const buffer = await streamBuffer((wb) => {
                const ws = wb.addWorksheet("Data");
                const series = [];
                for (let col = 1; col <= 254; col++) {
                    series.push({ values: columnRange(col) });
                }
                series.push({ values: "A1:XFD1" });
                ws.addChart({ type: "line", anchor: "A1:B2", series });
                for (let r = 1; r <= rows; r++) {
                    ws.addRow([r, r * 2, r * 3]).commit();
                }
            });
            return { ms: Number(process.hrtime.bigint() - started) / 1e6, buffer };
        };
        const small = await run(500);
        const large = await run(2000);
        const xml = text(large.buffer, "xl/charts/chart1.xml");
        expect(xml).to.include('<c:ptCount val="1048576"/>');
        expect(xml).to.include('<c:ptCount val="16384"/>');
        expect(xml).to.include('<c:pt idx="1999"><c:v>6000</c:v></c:pt>');
        // 4 times the rows: well under 16 times the time (quadratic)
        expect(large.ms).to.be.below(Math.max(small.ms, 50) * 10);
    });

    it("keeps the values captured compactly: a few bytes per number", async function () {
        this.timeout(60000);
        const gc = collector();
        if (!gc) {
            this.skip();
        }
        const used = () => {
            gc();
            const { heapUsed, arrayBuffers } = process.memoryUsage();
            return heapUsed + (arrayBuffers || 0);
        };
        const rows = 200000;
        // the memory held while the rows are written, with and without a chart of 2 series of the 200,000 rows
        const held = async (series) => {
            let growth = 0;
            await streamBuffer((wb) => {
                const ws = wb.addWorksheet("Data");
                if (series.length) {
                    ws.addChart({ type: "line", anchor: "E1:K9", series });
                }
                const base = used();
                for (let r = 1; r <= rows; r++) {
                    ws.addRow([r, r * 1.5, r * 2.5]).commit();
                }
                growth = used() - base;
            });
            return growth;
        };
        const without = await held([]);
        const withChart = await held([{ values: `B1:B${rows}` }, { values: `C1:C${rows}` }]);
        const perCell = (withChart - without) / (2 * rows);
        expect(perCell, `${perCell.toFixed(1)} bytes per cell`).to.be.below(40);
    });

    it("keeps many captures in a heap: thousands of charts on rows to come", async function () {
        this.timeout(20000);
        const started = Date.now();
        const buffer = await streamBuffer((wb) => {
            const ws = wb.addWorksheet("Data");
            // in decreasing order of first row: the worst order for a sorted list
            for (let i = 2000; i >= 1; i--) {
                ws.addChart({ type: "column", anchor: "D1:E2", series: [{ values: `A${i}:A${i + 4}` }] });
            }
            for (let r = 1; r <= 2004; r++) {
                ws.addRow([r]).commit();
            }
        });
        expect(Date.now() - started).to.be.below(15000);
        expect(text(buffer, "xl/charts/chart1.xml")).to.include('<c:pt idx="4"><c:v>2004</c:v></c:pt>');
        expect(text(buffer, "xl/charts/chart2000.xml")).to.include('<c:pt idx="0"><c:v>1</c:v></c:pt>');
    });
});

describe("Chartsheets of the streaming writer", () => {
    it("writes a chartsheet in its place among the sheets, its chart showing the data captured", async () => {
        let added;
        const buffer = await streamBuffer(async (wb) => {
            const data = wb.addWorksheet("Data");
            added = wb.addChartsheet("Sales Chart", {
                type: "column",
                title: "Sales",
                series: [{ name: { ref: "Data!B1" }, categories: "Data!A2:A5", values: "Data!$B$2:$B$5" }],
            });
            const after = wb.addWorksheet("After");
            expect(after.id).to.equal(3);
            expect(() => wb.addWorksheet("sales chart")).to.throw("Worksheet name already exists: sales chart");
            fill(data, { commit: true });
            await data.commit();
        });
        expect(added).to.deep.equal({ id: 2, name: "Sales Chart", state: "visible" });
        validate(buffer, "chartsheet");
        const workbook = text(buffer, "xl/workbook.xml");
        expect(workbook).to.match(
            /<sheet sheetId="1" name="Data"[^>]*\/><sheet sheetId="2" name="Sales Chart"[^>]*\/><sheet sheetId="3" name="After"/
        );
        expect(text(buffer, "[Content_Types].xml")).to.include(
            `<Override PartName="/xl/chartsheets/sheet1.xml" ContentType="${CT_CHARTSHEET}"/>`
        );
        expect(text(buffer, "xl/chartsheets/sheet1.xml")).to.equal(
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<chartsheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheetPr/><sheetViews><sheetView zoomToFit="1" workbookViewId="0"/></sheetViews><pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/><drawing r:id="rId1"/></chartsheet>'
        );
        expect(text(buffer, "xl/drawings/drawing1.xml")).to.include(
            '<xdr:absoluteAnchor><xdr:pos x="0" y="0"/><xdr:ext cx="9304587" cy="6077107"/>'
        );
        expect(text(buffer, "xl/charts/chart1.xml")).to.include('<c:pt idx="3"><c:v>14</c:v></c:pt>');
        expect(text(buffer, "docProps/app.xml")).to.include("<vt:lpstr>Charts</vt:lpstr></vt:variant><vt:variant><vt:i4>1</vt:i4>");
        const wb = await reload(buffer);
        expect(wb.chartsheets).to.deep.equal([{ id: 2, name: "Sales Chart", state: "visible" }]);
        expect(wb.worksheets.map((ws) => ws.name)).to.deep.equal(["Data", "After"]);
    });

    it("numbers the drawing of a chartsheet after those of the worksheets", async () => {
        const buffer = await streamBuffer((wb) => {
            const ws = wb.addWorksheet("Data");
            // added before the worksheet is committed (its drawing named)
            wb.addChartsheet("Pie", { type: "pie", series: [{ values: "Data!A1:A2" }] }, { state: "veryHidden" });
            ws.addChart({ type: "line", anchor: "C1:H9", series: [{ values: "A1:A2" }] });
            ws.addRow([1]);
            ws.addRow([2]);
        });
        validate(buffer, "chartsheet-numbering");
        expect(text(buffer, "xl/worksheets/_rels/sheet1.xml.rels")).to.include("../drawings/drawing1.xml");
        expect(text(buffer, "xl/chartsheets/_rels/sheet1.xml.rels")).to.include("../drawings/drawing2.xml");
        expect(text(buffer, "xl/drawings/_rels/drawing1.xml.rels")).to.include("../charts/chart1.xml");
        expect(text(buffer, "xl/drawings/_rels/drawing2.xml.rels")).to.include("../charts/chart2.xml");
        expect(text(buffer, "xl/charts/chart2.xml")).to.include("<c:pieChart>");
        expect(text(buffer, "xl/workbook.xml")).to.match(
            /<sheet sheetId="1" name="Data"[^>]*\/><sheet sheetId="2" name="Pie" state="veryHidden"/
        );
    });

    it("refuses invalid names, chart options and states", () => {
        const wb = new ExcelJS.stream.xlsx.WorkbookWriter({ stream: new PassThrough() });
        wb.addWorksheet("Data");
        wb.addChartsheet("Chart", { type: "line", series: [{ values: "Data!A1:A2" }] });
        const chart = { type: "line", series: [{ values: "Data!A1:A2" }] };
        const cases = [
            [() => wb.addChartsheet("data", chart), "Worksheet name already exists: data"],
            [() => wb.addChartsheet("CHART", chart), "Worksheet name already exists: CHART"],
            [() => wb.addChartsheet("", chart), "The name can't be empty."],
            [() => wb.addChartsheet("a/b", chart), "cannot include any of the following characters"],
            [() => wb.addChartsheet("'quoted", chart), "single quotation mark"],
            [() => wb.addChartsheet("History", chart), 'The name "History" is protected'],
            [() => wb.addChartsheet(undefined, chart), "The name has to be a string."],
            [
                () => wb.addChartsheet("New", { type: "line", series: [{ values: "A1:A2" }] }),
                'Invalid chart series 1 values: "A1:A2" names no worksheet',
            ],
            [() => wb.addChartsheet("New", { ...chart, anchor: "A1:B2" }), "The chart of a chartsheet has no anchor: it fills the sheet"],
            [() => wb.addChartsheet("New", { type: "line", series: [{ values: "Nope!A1:A2" }] }), 'there is no worksheet "Nope"'],
            [
                () => wb.addChartsheet("New", chart, { state: "shown" }),
                'Invalid chartsheet state: "shown", expected one of visible, hidden, veryHidden',
            ],
            [() => wb.addChartsheet("New", chart, "hidden"), "Invalid chartsheet options: expected an object"],
        ];
        for (const [call, message] of cases) {
            expect(call).to.throw(message);
        }
    });

    it("writes sample files (spec/out/charts-samples/streaming-*.xlsx) for Excel", async () => {
        fs.mkdirSync(SAMPLES, { recursive: true });
        const samples = {
            "streaming-worksheet": (wb) => {
                const ws = wb.addWorksheet("Data");
                ws.addChart(CHART);
                ws.addChart({
                    type: "column",
                    grouping: "stacked",
                    title: "Stacked",
                    anchor: "H20:O36",
                    series: [
                        { name: { ref: "B1" }, categories: "A2:A5", values: "B2:B5" },
                        { name: { ref: "C1" }, categories: "A2:A5", values: "C2:C5" },
                    ],
                });
                fill(ws, { commit: true });
            },
            "streaming-cross-sheet": async (wb) => {
                const summary = wb.addWorksheet("Summary");
                const data = wb.addWorksheet("Data");
                summary.addChart({
                    type: "pie",
                    title: "Share",
                    anchor: "A1:H16",
                    series: [{ categories: "Data!A2:A5", values: "Data!B2:B5" }],
                });
                await summary.commit();
                fill(data, { commit: true });
            },
            "streaming-data-committed-then-chart": async (wb) => {
                const data = wb.addWorksheet("Data");
                fill(data, { commit: true });
                await data.commit();
                const summary = wb.addWorksheet("Summary");
                summary.getCell("A1").value =
                    "The chart below shows Data, committed before it: no cached values (Excel draws it from the cells)";
                summary.addChart({ ...CHART, anchor: "A3:H20", series: CHART.series.map((item) => prefixed(item, "Data")) });
                wb.addChartsheet("Chart", {
                    type: "column",
                    title: "Committed data",
                    series: [{ name: { ref: "Data!B1" }, categories: "Data!A2:A5", values: "Data!B2:B5" }],
                });
            },
            "streaming-chartsheet": (wb) => {
                const ws = wb.addWorksheet("Data");
                wb.addChartsheet("Chart", {
                    type: "scatter",
                    line: true,
                    title: "Scatter",
                    series: [{ name: "North", xValues: "Data!B2:B5", yValues: "Data!C2:C5" }],
                });
                fill(ws, { commit: true });
            },
        };
        for (const [name, build] of Object.entries(samples)) {
            const buffer = await streamBuffer(build, { useStyles: true, useSharedStrings: true });
            validate(buffer, name.replace(/^streaming-/, "sample-"));
            fs.writeFileSync(path.join(SAMPLES, `${name}.xlsx`), buffer);
            await reload(buffer);
        }
    });
});

// a function collecting the garbage, if the runtime gives one (Node.js: through the V8 flag; Bun: Bun.gc)
function collector() {
    const { Bun } = globalThis;
    if (Bun) {
        return () => Bun.gc(true);
    }
    if (typeof global.gc === "function") {
        return global.gc;
    }
    try {
        require("v8").setFlagsFromString("--expose-gc");
        return require("vm").runInNewContext("gc");
    } catch {
        return undefined;
    }
}

// a series of CHART with its ranges on a worksheet
function prefixed(item, sheet) {
    const range = (value) => (typeof value === "string" ? `${sheet}!${value}` : value);
    const name = typeof item.name === "object" ? { ref: `${sheet}!${item.name.ref}` } : item.name;
    return { ...item, name, categories: range(item.categories), values: range(item.values) };
}

// a range of a whole column (1-based column number)
function columnRange(col) {
    let letters = "";
    for (let n = col; n > 0; n = Math.floor((n - 1) / 26)) {
        letters = String.fromCharCode(65 + ((n - 1) % 26)) + letters;
    }
    return `${letters}1:${letters}1048576`;
}
